import sqlite3
import sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DB_PATH = os.path.join(BASE, 'catalog.db')


def table_columns(db, table):
    return dict((row[1], row) for row in db.execute('PRAGMA table_info(%s)' % table))


