        raise RuntimeError('price_cents is not INTEGER NOT NULL DEFAULT 0')

    table_sql_row = db.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='products'"
    ).fetchone()
    normalized_sql = ''.join(table_sql_row[0].lower().split()) if table_sql_row else ''
    if 'check(price_cents>=0)' not in normalized_sql:
        raise RuntimeError('price_cents nonnegative constraint is missing')

    invalid = db.execute(
        'SELECT COUNT(*) FROM products WHERE price_cents IS NULL OR price_cents < 0'
    ).fetchone()[0]
    if invalid:
        raise RuntimeError('products contains invalid price_cents values')


