            'SELECT id, description FROM products ORDER BY id'
        ).fetchall()
        if upgraded_products != original_products:
            raise RuntimeError('product IDs or descriptions changed during upgrade')

        verify_v2(db)
        changed = db.execute(
            'UPDATE schema_version SET version = 2 WHERE version = 1'
        ).rowcount
        if changed != 1:
            raise RuntimeError('schema_version update did not affect exactly one row')
        if db.execute('SELECT version FROM schema_version').fetchone()[0] != 2:
            raise RuntimeError('schema_version verification failed')

        db.commit()
        print('catalog schema upgraded from version 1 to version 2')
        return 0
    except Exception as exc:
        db.rollback()
        sys.stderr.write('upgrade failed; all changes rolled back: %s\n' % exc)
        return 1
    finally:
        db.close()


if __name__ == '__main__':
    sys.exit(main())
